fn is_prime(n: i8) -> bool {
    // Numbers less than 2 are not prime
    if n < 2 {
        return false;
    }
    
    // Check divisors from 2 up to n-1
    for k in 2..n {
        if n % k == 0 {
            return false;
        }
    }
    
    true
}